function TokenBucket(options) {
    if (arguments.length > 0 && !(options instanceof Object)) {
        throw new RangeError("options must be an object");
    }

    const {
        capacity,
        refillPerSecond,
        now = Date.now
    } = options;

    // Validate capacity
    if (typeof capacity !== 'number' || Number.isFinite(capacity) !== true || capacity <= 0) {
        throw new RangeError("capacity must be a positive finite number");
    }

    // Validate refillPerSecond
    if (typeof refillPerSecond !== 'number' || Number.isFinite(refillPerSecond) !== true) {
        throw new RangeError("refillPerSecond must be a number");
    }

    // Store state
    let tokens = capacity; // Start full
    let lastNow = now(); // Reference time for refill calculation

    // Internal refill calculation
    function refill(currentTime) {
        const elapsedSeconds = (currentTime - lastNow) / 1000;
        if (elapsedSeconds > 0 && refillPerSecond > 0) {
            const addedTokens = elapsedSeconds * refillPerSecond;
            tokens = Math.min(capacity, tokens + addedTokens);
            lastNow = currentTime;
        }
    }

    return {
        tryTake(n) {
            // Validate n
            if (typeof n !== 'number' || Number.isFinite(n) !== true || n <= 0) {
                throw new RangeError("n must be a positive finite number");
            }

            // Check if we have enough tokens
            if (tokens >= n) {
                tokens -= n;
                return true;
            }
            return false;
        },

        available() {
            return tokens;
        },

        msUntil(n) {
            // Validate n
            if (typeof n !== 'number' || Number.isFinite(n) !== true || n <= 0) {
                throw new RangeError("n must be a positive finite number");
            }

            // Current time
            const currentTime = now();

            // Refill state
            refill(currentTime);

            // If n > capacity or refillPerSecond is 0, tokens can never reach n
            if (n > capacity || refillPerSecond === 0) {
                return Infinity;
            }

            // Calculate tokens needed
            const tokensNeeded = n - tokens;

            // If we already have enough
            if (tokensNeeded <= 0) {
                return 0;
            }

            // Calculate time needed in milliseconds
            const secondsNeeded = tokensNeeded / refillPerSecond;
            const msNeeded = Math.ceil(secondsNeeded * 1000);

            return msNeeded;
        }
    };
}

module.exports = { TokenBucket };

