        // Validate n
        if (typeof n !== 'number' || Number.isFinite(n) !== true || n <= 0) {
            throw new RangeError("n must be a positive finite number");
        }

        // Refill state with current time
        const currentTime = now();
        refill(currentTime);

        // Check if we have enough tokens
        if (tokens >= n) {
            tokens -= n;
            return true;
        }
        return false;
    },

    available() {
