        const currentTime = now();
        refill(currentTime);
        return tokens;
    },

    msUntil(n) {
        // Validate n
        if (typeof n !== 'number' || Number.isFinite(n) !== true || n <= 0) {
            throw new RangeError("n must be a positive finite number");
        }

        // Current time
        const currentTime = now();

        // Refill state
        refill(currentTime);

        // If n > capacity, tokens can never reach n
        if (n > capacity) {
            return Infinity;
        }

        // If refillPerSecond is 0 and we don't have enough tokens, it's impossible
        if (refillPerSecond === 0 && tokens < n) {
            return Infinity;
        }

        // Calculate tokens needed
        const tokensNeeded = n - tokens;

        // If we already have enough
        if (tokensNeeded <= 0) {
            return 0;
        }

        // Calculate time needed in milliseconds
        const secondsNeeded = tokensNeeded / refillPerSecond;
        const msNeeded = Math.ceil(secondsNeeded * 1000);

        return msNeeded;
    }
};

